// 水位按采样率折算：换档后同一个帧数在两档下代表的时长差三倍，只有折算成时长才是同一条约束。
const PRIME_FRAMES = Math.round(sampleRate * 0.12);
const MAX_FRAMES = Math.round(sampleRate * 0.2);

class PanelPcmPlayer extends AudioWorkletProcessor {
  constructor() {
    super();
    this.queue = [];
    this.readOffset = 0;
    this.queuedFrames = 0;
    this.primed = false;
    this.port.onmessage = (e) => {
      const samples = e.data; // Float32Array 交织立体声
      this.queue.push(samples);
      this.queuedFrames += samples.length / 2;
      // 超上限丢最旧，抗漂移累积。被丢的是队头 queue[0]，其中 readOffset 个样本已被 process
      // 消费并已从 queuedFrames 扣除，故只补扣剩余未读部分 (length − readOffset)；扣完复位。
      while (this.queuedFrames > MAX_FRAMES && this.queue.length > 1) {
        const dropped = this.queue.shift();
        this.queuedFrames -= (dropped.length - this.readOffset) / 2;
        this.readOffset = 0;
      }
    };
  }
  process(inputs, outputs) {
    // 蓄够水位再起播：跨网承载的到达间隔本就抖，见底即输出等于把每一次抖动都变成一次断音。
    if (!this.primed) {
      if (this.queuedFrames < PRIME_FRAMES) return true;
      this.primed = true;
    }
    const left = outputs[0][0];
    const right = outputs[0][1];
    let i = 0;
    while (i < left.length && this.queue.length > 0) {
      const chunk = this.queue[0];
      if (this.readOffset >= chunk.length) { this.queue.shift(); this.readOffset = 0; continue; }
      left[i] = chunk[this.readOffset];
      right[i] = chunk[this.readOffset + 1];
      this.readOffset += 2;
      this.queuedFrames -= 1;
      i += 1;
    }
    // 不足处保持 0（静音补齐）；见底即重新蓄水，否则往后每一帧都在临界点上抖。
    this.primed = this.queuedFrames > 0;
    return true;
  }
}
registerProcessor('panel-pcm-player', PanelPcmPlayer);
